  sync.browserAutomation = {
    ...(sync.browserAutomation || {}),
    status: 'normal_browser_open_requested',
    checkedAt: Date.now(),
    connected: false,
    note: '일반 Chrome에 Cafe24 일반 계정 로그인 화면을 여는 중입니다. 이 경로는 저장된 일반 계정 확인용이며 자동 클릭 대상은 아닙니다.',
  };
  sync.lastBrowserCheckedAt = sync.browserAutomation.checkedAt;
