    vmResults: [],
    vmGroupedResults: {},
    localResults: [],
    localGroupedResults: {},
    autoCapture: false,
    suppressFactoryCompetitorFallback: false,
    loading: false,
    phase: 'idle',
    status: '',
    route: '',
    searchId: '',
    vmBridgeJobId: '',
    searchRuns: [],
    siteSearchStatus: [],
    vmSearchAttempts: [],
    sessionId: '',
    detailJobId: '',
    vmCaptureStatus: {},
