async function factoryAddCompletedFiles(files, options = {}) {
  if (!options.factory) {
    const receipt = await factoryRuntimeUpdateOwnedFactory(
      'factory/assets:addFactoryCompletedFiles',
      'factory-assets',
      draft => factoryAddCompletedFiles(files, { ...options, factory: draft }),
    );
    return receipt.result;
  }
  const factory = options.factory;
  const currentRunId = typeof factoryCurrentWorkflowRunId === 'function'
    ? factoryCurrentWorkflowRunId(factory)
    : '';
  const productKey = typeof factoryCurrentProductKey === 'function'
    ? factoryCurrentProductKey(factory)
    : '';
  const inputImageFingerprint = typeof factoryCurrentInputImageFingerprint === 'function'
    ? factoryCurrentInputImageFingerprint(factory)
    : '';
  const imageFiles = Array.from(files || []).filter(file => file?.type?.startsWith('image/'));
  const added = await Promise.all(imageFiles.map(file => new Promise(resolve => {
    const reader = new FileReader();
    reader.onload = e => {
      const asset = factoryRegisterAsset('detail', e.target.result, {
        factory,
        title: file.name.replace(/\.[^.]+$/, '') || '직접 추가 완성본',
        currentRunId,
        generationRunId: currentRunId,
        productKey,
        inputImageFingerprint,
        metadata: { source: '사용자 직접 추가', fileName: file.name },
        used: true,
      });
      resolve(asset ? 1 : 0);
    };
    reader.onerror = () => resolve(0);
    reader.readAsDataURL(file);
  })));
  const count = added.reduce((sum, value) => sum + value, 0);
  factorySetStageStatus('detail', count ? 'done' : 'blocked', count ? `완성본 직접 추가 ${count}장` : '완성본 직접 추가 실패', factory);
  factoryLog(count ? `완성본 ${count}장을 직접 추가했습니다.` : '직접 추가할 완성본 이미지를 불러오지 못했습니다.', count ? 'ok' : 'warn', factory);
  saveLastWorkNow();
  if (options.render !== false) render();
  return count;
}

